import torch
import torch.nn as nn
import triton
import triton.language as tl


@triton.jit
def scan_add_op(a, b):
    return a + b


@triton.autotune(
    configs=[
        triton.Config({"BLOCK_SIZE": 512}, num_warps=4, num_stages=1),
    ],
    key=["N"],
)
@triton.jit
def cumsum_kernel(
    x_ptr,
    out_ptr,
    M,
    N,
    stride_xm,
    stride_om,
    BLOCK_SIZE: tl.constexpr,
):
    row_idx = tl.program_id(0)
    x_row = x_ptr + row_idx * stride_xm
    o_row = out_ptr + row_idx * stride_om

    running_total = 0.0

    for block_start in tl.range(0, N, BLOCK_SIZE):
        offsets = block_start + tl.arange(0, BLOCK_SIZE)
        col_mask = offsets < N

        x = tl.load(x_row + offsets, mask=col_mask, other=0.0).to(tl.float32)

        scanned = tl.associative_scan(x, axis=0, combine_fn=scan_add_op)
        result = scanned + running_total

        running_total = running_total + tl.sum(x, axis=0)

        tl.store(o_row + offsets, result.to(out_ptr.dtype.element_ty), mask=col_mask)


class Model(nn.Module):
    def __init__(self, dim):
        super(Model, self).__init__()
        self.dim = dim

    def forward(self, x, mask):
        masked = x.float() * mask.float()
        masked = masked.contiguous()
        M, N = masked.shape
        out = torch.empty_like(masked)

        grid = (M,)
        cumsum_kernel[grid](
            masked,
            out,
            M,
            N,
            masked.stride(0),
            out.stride(0),
        )
        return out


batch_size = 32768
input_shape = (32768,)
dim = 1


def get_inputs():
    x = torch.rand(batch_size, *input_shape)
    mask = torch.randint(0, 2, x.shape).bool()
    return [x, mask]


def get_init_inputs():
    return [dim]
